check "kube-proxy runs (ready) on $ALT_CP" bash -c "[ \"\$(kubectl --context alt -n kube-system get pods -l k8s-app=kube-proxy --field-selector spec.nodeName=$ALT_CP -o jsonpath='{.items[*].status.containerStatuses[0].ready}')\" = true ]"
check "kube-proxy's config uses a valid proxy mode" bash -c "kubectl --context alt -n kube-system get cm kube-proxy -o jsonpath='{.data.config\.conf}' | grep -Eq '^mode: *\"?(iptables|nftables|ipvs)?\"?\$'"
check "Service quotes (8080) answers on its ClusterIP from $ALT_CP" bash -c "ip=\$(kubectl --context alt -n api get svc quotes -o jsonpath='{.spec.clusterIP}'); [ \"\$(kubectl --context alt -n api get svc quotes -o jsonpath='{.spec.ports[0].port}')\" = 8080 ] && node_exec $ALT_CP \"curl -s -m 4 http://\$ip:8080/\" | grep -q 'it works'"
